import math


def permutation_factorial_sums(numbers):
    if not isinstance(numbers, list):
        raise TypeError("numbers must be a list of integers")
    for n in numbers:
        if isinstance(n, bool) or not isinstance(n, int):
            raise TypeError("numbers must be a list of integers")
    for n in numbers:
        if n < 0:
            raise ValueError("numbers must be non-negative")
    if not numbers:
        return ([], [])
    perms = list(itertools.permutations(numbers))
    fact_cache = {}

    def fact(n):
        if n not in fact_cache:
            fact_cache[n] = math.factorial(n)
        return fact_cache[n]

    sums = [sum(fact(x) for x in p) for p in perms]
    return (sums, perms)

