def map_keys_to_count_lists(keys, n_values):
    """Map each distinct key to its own list [1, 2, ..., n_values].

    Keys keep the order of their first appearance. Each key gets an
    independent list, so mutating one does not affect the others.
    """
    n = int(n_values)
    if n < 0:
        raise ValueError("n_values must be a non-negative integer")
    result = {}
    for key in keys:
        if key not in result:
            result[key] = list(range(1, n + 1))
    return result

