import json
from collections import Counter


_URL_PREFIXES = ("http://", "https://", "www.")


def count_urls_in_json(json_str, top_n=10):
    """Count URL string values in a JSON document, including nested values.

    A URL is a string value starting with 'http://', 'https://' or 'www.'.
    Returns a dict of the top_n most frequent URLs mapped to their counts.
    Raises ValueError if json_str is not valid JSON.
    """
    try:
        data = json.loads(json_str)
    except (TypeError, ValueError) as exc:
        raise ValueError("Invalid JSON input: {}".format(exc)) from exc

    counts = Counter()
    # Iterative traversal (avoids recursion limits); preserves document order.
    stack = [data]
    while stack:
        item = stack.pop()
        if isinstance(item, dict):
            stack.extend(reversed(list(item.values())))
        elif isinstance(item, list):
            stack.extend(reversed(item))
        elif isinstance(item, str):
            if item.startswith(_URL_PREFIXES):
                counts[item] += 1

    if top_n is None:
        return dict(counts.most_common())
    if top_n <= 0:
        return {}
    return dict(counts.most_common(top_n))

