def count_letter_frequencies(list_of_lists, filler):
    """Count letter occurrences across all sublists.

    Each empty sublist is counted as if it contained the letters in `filler`.
    Returns a plain dict mapping each letter to its count.
    """
    counts = Counter()
    filler_items = list(filler)
    for sub in list_of_lists:
        items = list(sub)
        if not items:
            counts.update(filler_items)
        else:
            counts.update(items)
    return dict(counts)

