def top_k_values(numbers, k):
    """Return the k largest values from numbers in descending order, keeping duplicates."""
    if k is None or k <= 0:
        return []
    numbers = list(numbers)
    if k >= len(numbers):
        return sorted(numbers, reverse=True)
    return heapq.nlargest(k, numbers)

